// Roll raw samples into fixed 10 second windows per machine and sensor.
// When a sample arrives that belongs to a new window, the previous window
// for that key is summarised and forwarded. edge_ts is stamped at that moment
// and is the start point for the end-to-end latency measurement.
const WINDOW_MS = 10000;
const p = msg.payload;
if (!p || p.value === undefined) return null;

const key = p.machine_id + '/' + p.sensor_type;
const windows = context.get('windows') || {};
const ws = Math.floor(p.ts / WINDOW_MS) * WINDOW_MS;

function summarise(w) {
    const n = w.values.length;
    const sum = w.values.reduce((a, b) => a + b, 0);
    const sumSq = w.values.reduce((a, b) => a + b * b, 0);
    return {
        edge_ts: Date.now(),
        window_start: w.window_start,
        window_end: w.window_start + WINDOW_MS,
        window: '10s',
        site_id: w.site_id,
        line_id: w.line_id,
        machine_id: w.machine_id,
        sensor_type: w.sensor_type,
        unit: w.unit,
        count: n,
        mean: Math.round(sum / n * 1000) / 1000,
        min: Math.min(...w.values),
        max: Math.max(...w.values),
        rms: Math.round(Math.sqrt(sumSq / n) * 1000) / 1000
    };
}

let w = windows[key];
let out = null;
if (w && w.window_start !== ws) {
    out = summarise(w);
    w = null;
}
if (!w) {
    w = {
        window_start: ws,
        site_id: p.site_id,
        line_id: p.line_id,
        machine_id: p.machine_id,
        sensor_type: p.sensor_type,
        unit: p.unit,
        values: []
    };
}
w.values.push(p.value);
windows[key] = w;
context.set('windows', windows);

if (!out) return null;
return {
    topic: 'linesentry/edge/' + out.site_id + '/' + out.line_id + '/' + out.machine_id + '/' + out.sensor_type,
    payload: out
};

// Exponentially weighted moving average on the window mean so one noisy
// window does not look like a fault. Alpha 0.3 gives roughly a 30 second
// memory at 10 second windows.
const ALPHA = 0.3;
const p = msg.payload;
const key = p.machine_id + '/' + p.sensor_type;
const state = context.get('ewma') || {};
const prev = state[key];
const smoothed = prev === undefined ? p.mean : ALPHA * p.mean + (1 - ALPHA) * prev;
state[key] = smoothed;
context.set('ewma', state);
p.smoothed = Math.round(smoothed * 1000) / 1000;
return msg;

// Only forward a window when the smoothed value has moved by a meaningful
// amount since the last one sent, or when a heartbeat is due. This is what
// keeps the cloud traffic low in steady state.
const DEADBAND = { vibration: 0.15, temperature: 1.0, current: 0.5, rpm: 20 };
const HEARTBEAT_MS = 60000;
const p = msg.payload;
const key = p.machine_id + '/' + p.sensor_type;
const last = context.get('last') || {};
const prev = last[key];
const band = DEADBAND[p.sensor_type] || 0;
const now = Date.now();

let reason = null;
if (!prev) reason = 'first';
else if (Math.abs(p.smoothed - prev.value) >= band) reason = 'changed';
else if (now - prev.sent >= HEARTBEAT_MS) reason = 'heartbeat';

// Keep a running count of what is dropped versus forwarded for the evidence
const stats = context.get('stats') || { forwarded: 0, dropped: 0 };
if (!reason) {
    stats.dropped++;
    context.set('stats', stats);
    return null;
}
stats.forwarded++;
context.set('stats', stats);
last[key] = { value: p.smoothed, sent: now };
context.set('last', last);
p.forward_reason = reason;
node.status({ fill: 'green', shape: 'dot', text: 'fwd ' + stats.forwarded + ' / drop ' + stats.dropped });
return msg;
